const required=['company_name','website','first_name','last_name','job_title','country','industry','employee_count'];
const items=$input.all();
return items.map(({json:r})=>{if(!r||typeof r!=='object')throw Error('Invalid lead');const missing=required.filter(k=>!String(r[k]??'').trim());return {json:{...r,_raw_records:items.length,validation_status:missing.length?'Incomplete':'Complete',missing_fields:missing.join('; ')}}});

const required=['company_name','website','first_name','last_name','job_title','country','industry','employee_count'];
const functions=[['Procurement',['procurement','sourcing']],['Supply Chain',['supply chain','logistics']],['Purchasing',['purchasing','buyer']],['Operations',['operations','plant manager']],['Human Resources',['human resources','people operations','hr ','hr manager']],['Talent Acquisition',['talent acquisition','recruiting','recruitment']]];
return $input.all().map(({json:r})=>{const v=Object.fromEntries(required.map(k=>[k,String(r[k]??'').trim().replace(/\s+/g,' ')]));
const country=v.country.toLowerCase().replace(/\./g,'');if(['us','usa','united states','united states of america'].includes(country))v.country='United States';
v.website=v.website.replace(/^https?:\/\//i,'').replace(/\/+$/,'').toLowerCase();
const count=v.employee_count.replace(/,/g,'');v.employee_count=/^\d+$/.test(count)&&Number(count)>0?String(Number(count)):'';
const title=v.job_title.toLowerCase();v.job_function=functions.find(([,terms])=>terms.some(t=>title.includes(t)))?.[0]??'Other';
const missing=required.filter(k=>!v[k]);return {json:{...v,_raw_records:r._raw_records,validation_status:missing.length?'Incomplete':'Complete',missing_fields:missing.join('; ')}}});

const required=['company_name','website','first_name','last_name','job_title','country','industry','employee_count'];
const has=(s,terms)=>terms.some(t=>s.includes(t));
const roundEven=n=>{const x=Math.floor(n);return n-x===.5?(x%2?x+1:x):Math.round(n)};
return $input.all().map(({json:r})=>{const t=r.job_title.toLowerCase(),i=r.industry.toLowerCase(),n=Number(r.employee_count||0);
const score_breakdown={
geography:r.country==='United States'?20:r.country?5:0,
industry:has(i,['manufactur','machinery','equipment','engineering','industrial'])?25:has(i,['construction','logistics','distribution','automation'])?13:i?3:0,
company_size:n>=20&&n<=1000?15:n?7:0,
seniority:has(t,['chief','vp','vice president','director','head of','owner','president'])?15:has(t,['manager','lead','supervisor'])?9:t?3:0,
job_function:r.job_function!=='Other'?15:t?3:0,
data_completeness:roundEven(10*required.filter(k=>!!r[k]).length/required.length)};
return {json:{...r,baseline_score:Object.values(score_breakdown).reduce((a,b)=>a+b,0),score_breakdown}}});

return $input.all().map(({json:r})=>{const fit=['manufactur','machinery','equipment','engineering','industrial'].some(t=>r.industry.toLowerCase().includes(t));
const n=Number(r.employee_count||0),ideal=r.country==='United States'&&fit&&n>=20&&n<=1000&&r.job_function!=='Other';
const assessment=ideal&&r.baseline_score>=75?'strong':r.baseline_score>=50?'moderate':'weak';
const company=r.company_name||'your team',role=r.job_function.toLowerCase(),industry=r.industry||"the company's sector";
return {json:{...r,ai_icp_assessment:assessment,ai_source:'mock',
qualification_reason:({strong:'Strong',moderate:'Partial',weak:'Limited'}[assessment])+' ICP fit: '+(r.country||'unknown location')+', '+industry+', '+(r.employee_count||'unknown')+' employees, '+role+' role.',
outreach_angle:r.job_function!=='Other'?'Explore how '+company+' handles '+role+' capacity and process consistency.':'Explore operational priorities at '+company+' before proposing a solution.',
personalized_opening:'Hi '+(r.first_name||'there')+', I noticed '+company+' works in '+industry+'; I\'d be interested in how your team approaches '+role+' priorities.'}}});

const rows=$input.all().map(i=>i.json);if(!rows.length)throw Error('No leads');
const summary={record_type:'summary',raw_records:rows[0]._raw_records,unique_leads:rows.length,hot:rows.filter(r=>r.priority==='Hot').length,warm:rows.filter(r=>r.priority==='Warm').length,cold:rows.filter(r=>r.priority==='Cold').length,average_score:Math.round(rows.reduce((a,r)=>a+r.final_score,0)/rows.length*100)/100};
if(summary.hot+summary.warm+summary.cold!==summary.unique_leads)throw Error('Priority totals do not match');
return [{json:summary}];
